// Bad: the logger receives finished text; LessonId is not a property.
logger.LogInformation($"Completed lesson {lessonId} for {userId}");

// Good: a template with positional placeholders.
logger.LogInformation("Completed lesson {LessonId} for {UserId}", lessonId, userId);

// Metrics for trends: a counter and a latency histogram.
private static readonly Meter Meter = new("Skillforge.Lessons");
private static readonly Counter<long> Completions = Meter.CreateCounter<long>("lessons.completed");
private static readonly Histogram<double> Latency = Meter.CreateHistogram<double>("lessons.complete.duration", unit: "ms");
